/* Câu hỏi các đề Tin học lớp 12 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- Tin học 12 · Kiểm tra cuối học kì I (Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng
     và Định hướng Khoa học máy tính, Bài 1–12; Phiên N12-ck1-tin-congnghe) ----------
     Phạm vi theo ma trận cuối kì I tra được (Bài 1, 3, 4, 6, 7–12; ở đây thêm Bài 2 và bài thực hành Bài 5), trọng tâm Bài 7–12 (HTML). Hai
     đề cố định 25 câu (Bài 1–6 11 câu, Bài 7–12 14 câu), chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng trên 12 chủ đề theo tên bài của sách
     (ma trận ở data/banks/index.js). Hai đề là kho của đề ngẫu nhiên "tin12-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này),
     nên ô (chủ đề, mức) nào cũng có đúng gấp đôi số câu ô đó rút; mỗi ô một ý riêng, để câu cùng chủ đề (đề "Ôn chủ đề" rút chung) không lộ
     đáp án của nhau. Câu hỏi tên thẻ chỉ hỏi thẻ không có trong mã của câu khác (hr, del, dd, caption, iframe, textarea; thuộc tính controls,
     kiểu password). Dạng câu theo khung Công văn 7991 và đề thi tốt nghiệp môn Tin học: nhiều lựa chọn, đúng/sai 4 ý (mỗi đề 3 câu, kiểu Đ/S
     không lặp), trả lời ngắn bằng số, 2 câu tự luận tự chấm (Đề 1: tin nhắn ứng xử trong nhóm học tập trực tuyến; Đề 2: viết mã HTML một
     bảng có ô gộp). Đoạn mã ngắn viết trong đề bài, lựa chọn, đặt trong ngoặc kép “…”; đoạn mã nhiều dòng vẽ thành hình “khung mã” (mỗi dòng
     một chữ, lùi đầu dòng theo độ sâu của thẻ). Thẻ, thuộc tính theo sách in năm 2026: không dùng target="_blank", <button>, checked,
     placeholder; không hỏi <u> còn được hỗ trợ hay không, cách hiển thị mặc định của <th>, hình dạng kí tự đầu dòng disc, circle, số cổng
     WAN của router (chỗ sách viết chưa thống nhất). tests/tin-congnghe12-ck1.js đọc lại mọi đoạn mã bằng một bộ đọc HTML nhỏ (đúng cú pháp,
     chỉ thẻ, thuộc tính sách dạy) rồi tính kết quả hiển thị để so với đáp án.
     Câu tự soạn, đối chiếu với sách in năm 2026; không dùng ví dụ, mã mẫu, bài tập của sách (ấm đun nước tự ngắt, cửa siêu thị, MYCIN,
     đoạn thơ «Vội vàng», phương trình bậc hai, hội chợ ẩm thực, câu lạc bộ Trường Nguyễn Bỉnh Khiêm, thư mục web/images, coffee.png, heart.png,
     ảnh 720 × 450, bưu cục, bảng định tuyến, thư mục “SÁCH LỚP 12”, máy in Canon, đăng kí môn thi tốt nghiệp). Cách xếp mức: nêu khái niệm, chức
     năng, tên thẻ, thuộc tính như sách là Biết; phân loại một trường hợp, đọc mã để biết kết quả hiển thị là Hiểu; chọn hoặc sửa mã cho một
     yêu cầu, tính kích thước, viết đường dẫn, xử lí tình huống là Vận dụng. */
  "tin12-ck1-de1": {
    note: "Sách Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng và Định hướng Khoa học máy tính. Phạm vi cuối học kì I theo ma trận đề tra được: Chủ đề 1 Máy tính và xã hội tri thức (Bài 1–2) 4 câu; Chủ đề 2 Mạng máy tính và Internet (Bài 3–5) 5 câu; Chủ đề 3 Đạo đức, pháp luật và văn hoá trong môi trường số (Bài 6) 2 câu; Chủ đề 4 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 7–12) 14 câu. Mã HTML được hỏi qua các đoạn mã trong đề và trong hình; không có phần thực hành trên máy. Trường đã học sang Bài 13 (CSS) hoặc có đề học kì I hỏi cả CSS thì phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Làm quen với Trí tuệ nhân tạo", type: "mc", q: "Khả năng nào sau đây là một đặc trưng của trí tuệ nhân tạo?",
        o: ["Học từ dữ liệu để tự điều chỉnh cách làm", "Lặp lại đúng một thao tác đã cài sẵn", "Lưu trữ được thật nhiều tệp dữ liệu", "Tính các phép cộng rất nhanh"],
        x: "Khả năng học là một đặc trưng của trí tuệ nhân tạo: hệ thống nắm bắt thông tin từ dữ liệu rồi điều chỉnh hành vi của mình. Lặp lại thao tác cài sẵn là tự động hoá; lưu trữ nhiều, tính nhanh là khả năng của mọi máy tính.", lv: 1 },
      { topic: "Làm quen với Trí tuệ nhân tạo", type: "tf4", q: "Mỗi ý sau về các thiết bị, phần mềm đúng hay sai?",
        o: ["Máy giặt tự ngắt khi hết thời gian đã cài đặt là một ứng dụng trí tuệ nhân tạo.", "Ứng dụng xem ảnh chụp lá cây rồi cho biết tên loài cây là một ứng dụng trí tuệ nhân tạo.", "Đèn đường tự bật khi cảm biến báo trời tối là một ứng dụng trí tuệ nhân tạo.", "Phần mềm nghe lời nói tiếng Việt rồi gõ thành văn bản có dấu là một ứng dụng trí tuệ nhân tạo."], a: [false, true, false, true],
        x: "a) Sai: máy chỉ làm theo thời gian cài sẵn, đó là tự động hoá. b) Đúng: nhận ra loài cây từ ảnh là khả năng nhận thức của trí tuệ nhân tạo. c) Sai: đèn bật theo một quy tắc cố định của cảm biến, không suy luận gì. d) Đúng: hiểu tiếng nói rồi chuyển thành chữ là khả năng hiểu ngôn ngữ của trí tuệ nhân tạo.", lv: 2 },
      { topic: "Trí tuệ nhân tạo trong khoa học và đời sống", type: "mc", q: "Ứng dụng trí tuệ nhân tạo nào sau đây thuộc lĩnh vực tài chính, ngân hàng?",
        o: ["Phát hiện giao dịch thẻ bất thường để cảnh báo gian lận", "Đọc ảnh X-quang để tìm dấu hiệu bệnh phổi", "Điều chỉnh đèn giao thông theo lượng xe", "Gợi ý bài luyện tập theo trình độ của từng học sinh"],
        x: "Phát hiện gian lận trong giao dịch là ứng dụng trong tài chính, ngân hàng; đọc ảnh X-quang thuộc y học; điều chỉnh đèn giao thông thuộc giao thông vận tải; gợi ý bài luyện tập theo trình độ thuộc giáo dục.", lv: 2 },
      { topic: "Trí tuệ nhân tạo trong khoa học và đời sống", type: "mc", q: "Một công ty dùng phần mềm trí tuệ nhân tạo để tự động loại bớt hồ sơ xin việc, nhưng khi ứng viên hỏi vì sao bị loại thì không ai giải thích được. Đây là biểu hiện của nguy cơ nào?",
        o: ["Thiếu minh bạch trong cách ra quyết định", "Áp lực thất nghiệp cho người lao động", "Bị kẻ xấu tấn công vào dữ liệu", "Lộ thông tin cá nhân của ứng viên"],
        x: "Phần mềm ra quyết định như một “hộp đen”, không giải thích được lí do và không rõ ai chịu trách nhiệm: đó là nguy cơ thiếu minh bạch. Tình huống không nói tới việc mất việc làm, tấn công dữ liệu hay lộ thông tin.", lv: 3 },
      { topic: "Một số thiết bị mạng thông dụng", type: "mc", q: "Khi nhận dữ liệu từ một máy tính gửi tới, bộ chia tín hiệu (hub) chuyển tín hiệu đi đâu?",
        o: ["Tới tất cả các cổng còn lại", "Chỉ tới cổng nối với máy nhận", "Ra Internet qua cổng WAN", "Quay lại cổng của máy gửi"],
        x: "Hub phát tín hiệu nhận được tới mọi cổng còn lại, nên khi nhiều máy cùng gửi dễ xảy ra xung đột tín hiệu. Bộ chuyển mạch (switch) mới xác định cổng nhận và chỉ chuyển dữ liệu tới cổng đó.", lv: 1 },
      { topic: "Một số thiết bị mạng thông dụng", type: "mc", q: "Nhà bạn Thu dùng Internet cáp quang. Thiết bị nào chuyển đổi tín hiệu ánh sáng trên cáp quang thành tín hiệu số cho mạng trong nhà?",
        o: ["Modem quang", "Switch", "Hub", "Cáp UTP và giắc RJ45"],
        x: "Mạng trong nhà dùng tín hiệu số, còn đường truyền của nhà cung cấp dùng tín hiệu ánh sáng trên cáp quang; modem quang chuyển đổi qua lại hai loại tín hiệu này. Switch, hub chỉ nối các máy trong mạng cục bộ, không chuyển đổi tín hiệu.", lv: 2 },
      { topic: "Giao thức mạng", type: "mc", q: "Khi một máy gửi thư điện tử tới máy chủ thư, máy đó dùng giao thức nào?",
        o: ["SMTP", "POP3", "IMAP", "HTTP"],
        x: "SMTP là giao thức dùng để gửi thư điện tử; POP3 và IMAP dùng để lấy thư từ máy chủ về.", lv: 1 },
      { topic: "Giao thức mạng", type: "tf4", q: "Mỗi ý sau về địa chỉ IPv4 đúng hay sai?",
        o: ["192.168.20.7 là một địa chỉ IPv4 viết đúng.", "8.8.4.4 là một địa chỉ IPv4 viết đúng.", "10.300.1.2 là một địa chỉ IPv4 viết đúng.", "172.16.5 là một địa chỉ IPv4 viết đúng."], a: [true, true, false, false],
        x: "Địa chỉ IPv4 là số 4 byte, viết thành 4 số thập phân ngăn bởi dấu chấm; mỗi số ứng với một byte nên chỉ từ 0 đến 255. a) Đúng. b) Đúng. c) Sai: 300 lớn hơn 255. d) Sai: chỉ có 3 số.", lv: 2 },
      { topic: "Thực hành chia sẻ tài nguyên trên mạng", type: "mc", q: "Cô giáo chia sẻ thư mục “Đề luyện tập” trên máy của cô qua mạng cục bộ cho cả lớp (Everyone). Cô muốn các bạn chỉ mở xem được, không sửa hay xoá được tệp. Cô nên chọn mức quyền nào?",
        o: ["Chọn Read", "Chọn Read/Write", "Chọn Remove", "Để trống"],
        x: "Mức quyền Read chỉ cho xem nội dung; Read/Write cho cả đọc và sửa; Remove là bỏ quyền của người dùng đó, các bạn sẽ không mở được thư mục.", lv: 3 },
      { topic: "Giao tiếp và ứng xử trong không gian mạng", type: "mc", q: "Vì sao trao đổi bằng tin nhắn chữ trên mạng dễ gây hiểu lầm hơn khi nói chuyện trực tiếp?",
        o: ["Người đọc không thấy nét mặt, cử chỉ, giọng nói", "Tin nhắn chữ luôn bị lỗi phông khi gửi sang máy khác", "Người nhận không đọc được chữ tiếng Việt có dấu", "Tin nhắn chữ chỉ gửi được khi cả hai cùng trực tuyến"],
        x: "Khi nói trực tiếp, nét mặt, cử chỉ, giọng nói giúp hiểu đúng ý người nói; tin nhắn chữ thiếu các tín hiệu phi ngôn ngữ này nên một câu có thể bị hiểu theo nghĩa khác.", lv: 1 },
      { topic: "Giao tiếp và ứng xử trong không gian mạng", type: "essay", q: "Trong nhóm học tập trực tuyến của lớp, hai bạn tranh cãi gay gắt về cách làm bài tập lớn và bắt đầu dùng lời lẽ nặng nề với nhau. Em là nhóm trưởng. Em hãy viết một tin nhắn (khoảng 4–6 câu) gửi cả nhóm để làm dịu không khí và đưa cuộc trao đổi trở lại đúng hướng.",
        rubric: [{ c: "Lời lẽ lịch sự, bình tĩnh; không chê bai, không nói nặng bạn nào", p: 0.5 }, { c: "Ghi nhận ý kiến của cả hai bạn, thể hiện sự tôn trọng, thấu hiểu (ai cũng muốn bài làm tốt)", p: 0.5 }, { c: "Nhắc cả nhóm tranh luận về ý kiến, không công kích người nói", p: 0.5 }, { c: "Đề xuất cách làm tiếp cụ thể (mỗi bạn nêu lí do, cả nhóm cùng chọn, hoặc hẹn gọi video để bàn)", p: 0.5 }],
        x: "Bài gợi ý: Chào cả nhóm, mình thấy hai bạn đều rất muốn bài làm của nhóm thật tốt nên mới tranh luận sôi nổi như vậy. Mình đề nghị cả nhóm dừng những lời nặng nề lại, mình bàn về cách làm chứ không bàn về người. Mỗi bạn hãy viết ngắn gọn cách làm của mình và lí do. Tối nay 8 giờ cả nhóm gọi video 15 phút để chọn cách làm nhé. Cảm ơn mọi người!", lv: 3 },
      { topic: "HTML và cấu trúc trang web", type: "mc", q: "HTML là gì?",
        o: ["Ngôn ngữ đánh dấu siêu văn bản, dùng để tạo trang web", "Giao thức truyền tải siêu văn bản giữa các máy tính", "Phần mềm trình duyệt dùng để xem trang web", "Ngôn ngữ lập trình để viết ứng dụng điện thoại"],
        x: "HTML (Hypertext Markup Language) là ngôn ngữ đánh dấu siêu văn bản: bộ quy tắc để tạo cấu trúc và hiển thị nội dung của trang web; trình duyệt đọc tệp HTML rồi hiển thị trang.", lv: 1 },
      { topic: "HTML và cấu trúc trang web", type: "mc", q: "Trình duyệt hiển thị dòng chữ nào ở tiêu đề (tab) của trang web viết bằng mã trong hình?",
        svg: '<svg viewBox="0 0 320 242"><rect x="1" y="1" width="318" height="240" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;!DOCTYPE html&gt;</text><text x="12" y="46" font-size="14">&lt;html&gt;</text><text x="28" y="66" font-size="14">&lt;head&gt;</text><text x="44" y="86" font-size="14">&lt;meta charset="utf-8"&gt;</text><text x="44" y="106" font-size="14">&lt;title&gt;Góc đọc sách&lt;/title&gt;</text><text x="28" y="126" font-size="14">&lt;/head&gt;</text><text x="28" y="146" font-size="14">&lt;body&gt;</text><text x="44" y="166" font-size="14">&lt;h1&gt;Sách hay tháng 11&lt;/h1&gt;</text><text x="44" y="186" font-size="14">&lt;p&gt;Mời các bạn ghé thư viện.&lt;/p&gt;</text><text x="28" y="206" font-size="14">&lt;/body&gt;</text><text x="12" y="226" font-size="14">&lt;/html&gt;</text></svg>',
        o: ["Góc đọc sách", "Sách hay tháng 11", "Mời các bạn ghé thư viện.", "utf-8"],
        x: "Nội dung của phần tử title (nằm trong head) là tên của trang web: hiện trên tab của trình duyệt và khi trang có trong kết quả tìm kiếm; chữ trong body mới hiện ở vùng nội dung của trang.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Thẻ nào tạo một đường kẻ ngang trên trang web?",
        o: ["<hr>", "<br>", "<p>", "<h1>"],
        x: "Thẻ đơn <hr> tạo một đường kẻ ngang để ngăn cách các phần của trang.", lv: 1 },
      { topic: "Định dạng văn bản", type: "mc", q: "Dòng chữ thứ hai trên trang web hiển thị từ đoạn mã trong hình là gì?",
        svg: '<svg viewBox="0 0 320 82"><rect x="1" y="1" width="318" height="80" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;p&gt;Mùa thu</text><text x="28" y="46" font-size="14">về trên phố&lt;/p&gt;</text><text x="12" y="66" font-size="14">&lt;p&gt;Lá vàng&lt;br&gt;rơi nhẹ&lt;/p&gt;</text></svg>',
        o: ["Lá vàng", "về trên phố", "Lá vàng rơi nhẹ", "rơi nhẹ"],
        x: "Trình duyệt coi chỗ xuống dòng trong mã như một dấu cách, nên dòng đầu là “Mùa thu về trên phố”. Thẻ br ngắt dòng, nên đoạn thứ hai hiện thành hai dòng: “Lá vàng” rồi “rơi nhẹ”.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Cần hiển thị dòng chữ “Diện tích hình vuông là a²”, trong đó chỉ chữ “là” được in đậm và số 2 là chỉ số trên. Đoạn mã nào đúng?",
        o: ["<p>Diện tích hình vuông <strong>là</strong> a<sup>2</sup></p>", "<p>Diện tích hình vuông <strong>là</strong> a<sub>2</sub></p>", "<p>Diện tích hình vuông <em>là</em> a<sup>2</sup></p>", "<p>Diện tích hình vuông <strong>là a<sup>2</sup></strong></p>"],
        x: "Thẻ strong chỉ in đậm phần chữ nằm giữa thẻ mở và thẻ đóng của nó, nên chỉ bao quanh chữ “là”; thẻ sup tạo chỉ số trên, sub tạo chỉ số dưới, em làm chữ nghiêng.", lv: 3 },
      { topic: "Tạo danh sách, bảng", type: "mc", q: "Trong danh sách mô tả (thẻ <dl>), thẻ nào chứa phần mô tả, giải thích cho từng mục?",
        o: ["<dd>", "<dt>", "<li>", "<td>"],
        x: "Trong danh sách mô tả, dt chứa tên mục (thuật ngữ, nhãn), còn dd chứa phần mô tả cho mục đó.", lv: 1 },
      { topic: "Tạo danh sách, bảng", type: "mc", q: "Với đoạn mã “<ol type=\"A\" start=\"3\"><li>Cầu lông</li><li>Đá cầu</li><li>Bơi</li></ol>”, mục “Bơi” có kí hiệu đầu dòng nào?",
        o: ["E", "C", "3", "c"],
        x: "type=\"A\" đánh dấu các mục bằng chữ cái in hoa; start=\"3\" bắt đầu từ chữ cái thứ ba là C. Ba mục lần lượt mang kí hiệu C, D, E, nên “Bơi” mang kí hiệu E.", lv: 2 },
      { topic: "Tạo danh sách, bảng", type: "mc", q: "Bảng tạo bởi đoạn mã trong hình gồm mấy hàng, mấy cột?",
        svg: '<svg viewBox="0 0 320 302"><rect x="1" y="1" width="318" height="300" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;table border="1"&gt;</text><text x="28" y="46" font-size="14">&lt;tr&gt;</text><text x="44" y="66" font-size="14">&lt;th rowspan="2"&gt;Tổ&lt;/th&gt;</text><text x="44" y="86" font-size="14">&lt;th colspan="2"&gt;Tuần&lt;/th&gt;</text><text x="28" y="106" font-size="14">&lt;/tr&gt;</text><text x="28" y="126" font-size="14">&lt;tr&gt;</text><text x="44" y="146" font-size="14">&lt;th&gt;1&lt;/th&gt;</text><text x="44" y="166" font-size="14">&lt;th&gt;2&lt;/th&gt;</text><text x="28" y="186" font-size="14">&lt;/tr&gt;</text><text x="28" y="206" font-size="14">&lt;tr&gt;</text><text x="44" y="226" font-size="14">&lt;td&gt;Tổ 1&lt;/td&gt;</text><text x="44" y="246" font-size="14">&lt;td colspan="2"&gt;Lau bảng&lt;/td&gt;</text><text x="28" y="266" font-size="14">&lt;/tr&gt;</text><text x="12" y="286" font-size="14">&lt;/table&gt;</text></svg>',
        o: ["3 hàng, 3 cột", "3 hàng, 4 cột", "2 hàng, 3 cột", "3 hàng, 5 cột"],
        x: "Có 3 thẻ tr nên bảng có 3 hàng. Hàng 1 có ô “Tổ” (kéo dài xuống hàng 2) và ô “Tuần” rộng 2 cột, tổng 3 cột; ở hàng 2, cột đầu là phần kéo dài của ô “Tổ”, thêm 2 ô; hàng 3 có ô “Tổ 1” và ô “Lau bảng” rộng 2 cột.", lv: 3 },
      { topic: "Tạo liên kết", type: "mc", q: "Đường dẫn nào sau đây là đường dẫn tuyệt đối?",
        o: ["https://example.com/tin/moi.html", "../thu-vien/tin/moi.html", "thu-vien/tin/sach-moi.html", "../../tin/sach-moi.html"],
        x: "Đường dẫn tuyệt đối có đủ giao thức (https://), tên miền và đường dẫn tới tệp; các đường dẫn còn lại được tính từ vị trí của tệp đang mở nên là đường dẫn tương đối.", lv: 1 },
      { topic: "Tạo liên kết", type: "mc", q: "Thư mục gốc của một website có tệp gioi-thieu.html và thư mục clb; trong thư mục clb có thư mục the-thao chứa tệp bong-da.html. Trong tệp bong-da.html, liên kết tới tệp gioi-thieu.html cần có href nào?",
        o: ["../../gioi-thieu.html", "../gioi-thieu.html", "gioi-thieu.html", "clb/the-thao/gioi-thieu.html"],
        x: "Tệp bong-da.html nằm trong clb/the-thao, thấp hơn thư mục gốc hai cấp; mỗi cụm “../” đi lên một cấp, nên cần “../../” rồi mới tới gioi-thieu.html.", lv: 3 },
      { topic: "Chèn tệp tin đa phương tiện và khung nội tuyến vào trang web", type: "mc", q: "Thẻ nào dùng để nhúng một trang web khác (ví dụ bản đồ trực tuyến) vào một khung bên trong trang hiện tại?",
        o: ["<iframe>", "<audio>", "<video>", "<source>"],
        x: "Thẻ iframe (khung nội tuyến) tạo một khung nhìn hiển thị tài nguyên web khác ngay trong trang; các trang chia sẻ video, bản đồ thường cho sẵn mã iframe để nhúng.", lv: 1 },
      { topic: "Chèn tệp tin đa phương tiện và khung nội tuyến vào trang web", type: "num", q: "Ảnh banner.png có kích thước gốc rộng 800 pixel, cao 300 pixel. Mã “<img src=\"banner.png\" width=\"400\">” hiển thị ảnh cao bao nhiêu pixel?", ans: 150, unit: "pixel",
        x: "Chỉ ghi chiều rộng thì chiều cao được giữ theo tỉ lệ của ảnh gốc: chiều rộng giảm từ 800 xuống 400 (một nửa) nên chiều cao còn 300 : 2 = 150 (pixel).", lv: 2 },
      { topic: "Tạo biểu mẫu", type: "mc", q: "Ô nhập nào làm các kí tự người dùng gõ vào bị che đi (ví dụ hiện thành dấu chấm)?",
        o: ["type=\"password\"", "type=\"number\"", "type=\"submit\"", "type=\"checkbox\""],
        x: "Kiểu password dùng cho ô nhập mật khẩu: các kí tự gõ vào bị che đi.", lv: 1 },
      { topic: "Tạo biểu mẫu", type: "tf4", q: "Mỗi ý sau về biểu mẫu tạo bởi đoạn mã trong hình đúng hay sai?",
        svg: '<svg viewBox="0 0 320 162"><rect x="1" y="1" width="318" height="160" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;form&gt;</text><text x="28" y="46" font-size="14">&lt;input type="radio" name="b"&gt; Sáng</text><text x="28" y="66" font-size="14">&lt;input type="radio" name="b"&gt; Chiều</text><text x="28" y="86" font-size="14">&lt;br&gt;</text><text x="28" y="106" font-size="14">&lt;input type="checkbox" name="m"&gt; Bơi</text><text x="28" y="126" font-size="14">&lt;input type="checkbox" name="m"&gt; Vẽ</text><text x="12" y="146" font-size="14">&lt;/form&gt;</text></svg>',
        o: ["Có thể chọn cùng lúc cả “Sáng” và “Chiều”.", "Có thể chọn cùng lúc cả “Bơi” và “Vẽ”.", "Nếu đổi name của ô “Chiều” thành name=\"c\" thì chọn được cả “Sáng” và “Chiều” cùng lúc.", "Nếu đổi hai ô “Bơi”, “Vẽ” thành type=\"radio\" (giữ name=\"m\") thì vẫn chọn được cả hai cùng lúc."], a: [false, true, true, false],
        x: "Các ô radio cùng name tạo thành một nhóm, mỗi lúc chỉ chọn được một ô; mỗi ô checkbox được chọn hay bỏ độc lập. a) Sai: hai ô “Sáng”, “Chiều” cùng name=\"b\". b) Đúng: hai ô checkbox chọn được cùng lúc. c) Đúng: khác name thì hai ô radio thuộc hai nhóm khác nhau. d) Sai: thành radio cùng name=\"m\" thì chỉ chọn được một ô.", lv: 3 }
    ]
  },
  "tin12-ck1-de2": {
    note: "Sách Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng và Định hướng Khoa học máy tính. Phạm vi cuối học kì I theo ma trận đề tra được: Chủ đề 1 Máy tính và xã hội tri thức (Bài 1–2) 4 câu; Chủ đề 2 Mạng máy tính và Internet (Bài 3–5) 5 câu; Chủ đề 3 Đạo đức, pháp luật và văn hoá trong môi trường số (Bài 6) 2 câu; Chủ đề 4 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 7–12) 14 câu. Mã HTML được hỏi qua các đoạn mã trong đề và trong hình; không có phần thực hành trên máy. Trường đã học sang Bài 13 (CSS) hoặc có đề học kì I hỏi cả CSS thì phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Làm quen với Trí tuệ nhân tạo", type: "mc", q: "Trí tuệ nhân tạo hẹp (còn gọi là trí tuệ nhân tạo yếu) là loại trí tuệ nhân tạo như thế nào?",
        o: ["Chỉ làm tốt một nhiệm vụ cụ thể", "Tự học, tự thích nghi, làm được nhiều việc như con người", "Không cần dữ liệu mà vẫn tự học được", "Chỉ chạy được trên các siêu máy tính"],
        x: "Trí tuệ nhân tạo hẹp được tạo ra để làm một nhiệm vụ cụ thể, như dịch văn bản hay nhận dạng biển số xe. Loại tự học, tự thích nghi, làm được nhiều việc như con người là trí tuệ nhân tạo tổng quát, hiện chưa đạt được.", lv: 1 },
      { topic: "Làm quen với Trí tuệ nhân tạo", type: "mc", q: "Một phần mềm tư vấn trồng trọt hỏi người dùng về loại đất, lượng mưa, rồi dùng các luật dạng “nếu … thì …” do kĩ sư nông nghiệp xây dựng để gợi ý loại cây nên trồng. Phần mềm này thuộc loại nào?",
        o: ["Hệ chuyên gia", "Trợ lí ảo", "Hệ thống nhận dạng hình ảnh", "Phần mềm dịch tự động"],
        x: "Hệ chuyên gia mô phỏng cách ra quyết định của chuyên gia bằng các luật suy diễn “nếu … thì …”, xây dựng từ tri thức của chuyên gia trong một lĩnh vực.", lv: 2 },
      { topic: "Trí tuệ nhân tạo trong khoa học và đời sống", type: "mc", q: "Ứng dụng nào sau đây là ứng dụng trí tuệ nhân tạo tạo sinh?",
        o: ["Vẽ tranh minh hoạ theo đoạn mô tả bằng lời", "Lọc thư rác ra khỏi hộp thư đến", "Nhận ra biển số của xe ra vào bãi đỗ", "Dự báo lượng mưa của ngày mai"],
        x: "Trí tuệ nhân tạo tạo sinh tự tạo ra nội dung mới (văn bản, hình ảnh, âm thanh); vẽ tranh theo mô tả là tạo nội dung mới. Lọc thư rác, nhận dạng biển số, dự báo thời tiết chỉ phân loại, nhận dạng hay dự đoán.", lv: 2 },
      { topic: "Trí tuệ nhân tạo trong khoa học và đời sống", type: "tf4", q: "Bạn Khánh dùng một ứng dụng hỏi đáp có trí tuệ nhân tạo để ôn tập lịch sử. Mỗi ý sau đúng hay sai?",
        o: ["Câu trả lời của ứng dụng có thể sai, nên Khánh cần đối chiếu với sách giáo khoa.", "Ứng dụng trả lời trôi chảy như người nên mọi thông tin nó đưa ra đều đúng.", "Nhập số điện thoại, địa chỉ nhà vào ứng dụng không ảnh hưởng gì tới quyền riêng tư.", "Chép nguyên câu trả lời của ứng dụng rồi nộp như bài tự làm là không trung thực."], a: [true, false, false, true],
        x: "a) Đúng: ứng dụng có thể đưa ra thông tin sai, cần kiểm tra lại bằng nguồn tin cậy. b) Sai: lời văn trôi chảy không bảo đảm nội dung đúng. c) Sai: dữ liệu cá nhân nhập vào có thể bị thu thập, sử dụng, ảnh hưởng tới quyền riêng tư. d) Đúng: dùng câu trả lời của ứng dụng như bài tự làm là thiếu trung thực.", lv: 3 },
      { topic: "Một số thiết bị mạng thông dụng", type: "mc", q: "Thiết bị nào chọn đường đi (định tuyến) cho dữ liệu từ mạng cục bộ ra các mạng khác như Internet?",
        o: ["Bộ định tuyến (router)", "Bộ chia tín hiệu (hub)", "Bộ chuyển mạch (switch)", "Giắc cắm RJ45"],
        x: "Bộ định tuyến có cổng LAN nối với mạng cục bộ và cổng WAN nối ra ngoài; nó chọn cổng để chuyển dữ liệu đi, gọi là định tuyến. Hub, switch chỉ nối các máy trong cùng mạng cục bộ.", lv: 1 },
      { topic: "Một số thiết bị mạng thông dụng", type: "mc", q: "Một quán cà phê muốn khách dùng điện thoại, máy tính xách tay truy cập mạng của quán mà không phải cắm dây. Quán cần thêm thiết bị nào vào mạng?",
        o: ["Điểm truy cập không dây (Access Point)", "Bộ chia tín hiệu (hub) có nhiều cổng", "Thêm cáp UTP và giắc RJ45 tới mỗi bàn", "Thêm một bộ chuyển mạch (switch) cho khách"],
        x: "Điểm truy cập không dây (bộ thu phát Wi-Fi) truyền nhận dữ liệu bằng sóng vô tuyến điện, giúp thiết bị kết nối vào mạng mà không cần dây.", lv: 2 },
      { topic: "Giao thức mạng", type: "mc", q: "Trong bộ giao thức TCP/IP, giao thức TCP đảm nhận việc nào sau đây?",
        o: ["Chia dữ liệu thành gói, đánh số và yêu cầu gửi lại gói bị lỗi", "Đánh địa chỉ và chọn đường cho gói tin giữa các mạng", "Đổi tín hiệu số thành tín hiệu quang", "Gửi thư điện tử từ máy người dùng tới máy chủ thư"],
        x: "TCP cắt dữ liệu thành các gói có đánh số để bên nhận ráp đúng thứ tự, dùng cơ chế xác nhận để yêu cầu gửi lại gói hỏng hoặc thất lạc. Đánh địa chỉ, chọn đường là việc của IP.", lv: 1 },
      { topic: "Giao thức mạng", type: "mc", q: "Khi gõ tên miền của một trang web vào trình duyệt, máy tính cần biết địa chỉ IP của máy chủ chứa trang đó. Hệ thống nào giúp đổi tên miền thành địa chỉ IP?",
        o: ["DNS", "HTTP", "TCP", "IMAP"],
        x: "Hệ thống tên miền (DNS) cho phép dùng tên bằng chữ dễ nhớ thay cho địa chỉ IP và đổi tên miền thành địa chỉ IP tương ứng.", lv: 2 },
      { topic: "Thực hành chia sẻ tài nguyên trên mạng", type: "mc", q: "Văn phòng có 5 máy tính nối với nhau trong một mạng cục bộ, nhưng chỉ máy của chị Hà có máy in. Làm thế nào để cả 5 máy đều in được bằng máy in này qua mạng?",
        o: ["Chia sẻ máy in ở máy chị Hà, máy khác thêm máy in mạng đó", "Mỗi lần in thì chép tệp sang máy chị Hà bằng USB", "Chia sẻ thư mục Public trên máy chị Hà cho cả văn phòng", "Đặt mạng của các máy ở chế độ Public để ai cũng thấy nhau"],
        x: "Chia sẻ máy in trên máy chị Hà (máy đó trở thành máy chủ in), rồi ở các máy khác thêm máy in mạng này; yêu cầu in từ các máy được xếp vào hàng đợi trên máy chị Hà. Chép tệp bằng USB không in qua mạng; chia sẻ thư mục chỉ cho dùng chung tệp, không cho dùng chung máy in; mạng Public dùng ở nơi công cộng, không nên bật chia sẻ.", lv: 3 },
      { topic: "Giao tiếp và ứng xử trong không gian mạng", type: "mc", q: "Ưu điểm nào sau đây là của giao tiếp trong không gian mạng?",
        o: ["Trao đổi được mọi lúc, mọi nơi khi có kết nối mạng", "Không bao giờ bị lộ thông tin cá nhân", "Dễ tạo quan hệ thân thiết hơn khi gặp mặt", "Không phụ thuộc vào thiết bị và đường truyền"],
        x: "Chỉ cần có kết nối mạng là trao đổi được dù ở đâu, vào lúc nào; giao tiếp trên mạng còn tiết kiệm thời gian, chi phí. Ngược lại, giao tiếp trên mạng có nguy cơ lộ thông tin, khó xây dựng quan hệ chặt chẽ và phụ thuộc vào thiết bị, đường truyền.", lv: 1 },
      { topic: "Giao tiếp và ứng xử trong không gian mạng", type: "mc", q: "Hải được câu lạc bộ khoa học của trường hẹn phỏng vấn qua gọi video. Việc nào sau đây phù hợp nhất?",
        o: ["Mặc lịch sự, ngồi ở nơi yên tĩnh, phía sau gọn gàng", "Vừa phỏng vấn vừa ăn sáng cho đỡ mất thời gian", "Tắt camera suốt buổi mà không báo trước với người hỏi", "Ngồi ở quán cà phê đông người cho mạng nhanh hơn"],
        x: "Khi gọi video, người khác nhìn thấy trang phục và khung cảnh phía sau mình; chọn trang phục lịch sự, chỗ ngồi yên tĩnh, gọn gàng thể hiện sự tôn trọng người đối diện.", lv: 3 },
      { topic: "HTML và cấu trúc trang web", type: "mc", q: "Một phần tử HTML như “<p>Chào bạn</p>” gồm những phần nào?",
        o: ["Thẻ bắt đầu, nội dung và thẻ kết thúc", "Tên tệp, nội dung và phần mở rộng .html", "Thuộc tính, giá trị và dấu chấm phẩy", "Thẻ head, thẻ body và thẻ title"],
        x: "Phần tử HTML gồm thẻ bắt đầu (p), nội dung ở giữa và thẻ kết thúc (có thêm dấu /); thẻ đơn chỉ có thẻ bắt đầu.", lv: 1 },
      { topic: "HTML và cấu trúc trang web", type: "mc", q: "Trong đoạn mã “<body><div><p>Bạn <em>Nhi</em> chào cả lớp.</p></div></body>”, phần tử nào là phần tử cha trực tiếp của phần tử p?",
        o: ["Phần tử div", "Phần tử em", "Phần tử body", "Phần tử html"],
        x: "Phần tử p nằm ngay bên trong phần tử div, còn div nằm trong body; em là phần tử con của p. Vậy div là cha trực tiếp của p.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Thẻ nào hiển thị chữ có một đường gạch ngang ở giữa, thường dùng để đánh dấu phần chữ bị xoá?",
        o: ["<del>", "<mark>", "<small>", "<sub>"],
        x: "Thẻ del đánh dấu phần chữ bị xoá bằng một đường gạch giữa chữ; mark làm nổi bật (highlight) chữ, small làm giảm cỡ chữ, sub tạo chỉ số dưới.", lv: 1 },
      { topic: "Định dạng văn bản", type: "mc", q: "Đoạn mã trong hình hiển thị trên trang web thành các dòng chữ. Chữ “Lớp 12A3” nằm ở đâu?",
        svg: '<svg viewBox="0 0 320 102"><rect x="1" y="1" width="318" height="100" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;span&gt;Họ tên:&lt;/span&gt;</text><text x="12" y="46" font-size="14">&lt;span&gt;Lê Ngọc Ánh&lt;/span&gt;</text><text x="12" y="66" font-size="14">&lt;div&gt;Lớp 12A3&lt;/div&gt;</text><text x="12" y="86" font-size="14">&lt;span&gt;Tổ 2&lt;/span&gt;</text></svg>',
        o: ["Một mình trên dòng thứ hai", "Cùng dòng với chữ “Họ tên: Lê Ngọc Ánh”", "Cùng dòng với chữ “Tổ 2”", "Không hiện ra vì div chỉ dùng trong head"],
        x: "Thẻ div tạo một khối bắt đầu trên dòng mới, còn span nằm trên cùng dòng với chữ xung quanh. Vì vậy trang hiện ba dòng: “Họ tên: Lê Ngọc Ánh”, “Lớp 12A3”, “Tổ 2”.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Cần hiển thị dòng “Giảm giá 20%” màu đỏ, cỡ chữ 24px. Đoạn mã nào đúng?",
        o: ["<p style=\"color: red; font-size: 24px\">Giảm giá 20%</p>", "<p style=\"color: red, font-size: 24px\">Giảm giá 20%</p>", "<p style=\"color: 24px; font-size: red\">Giảm giá 20%</p>", "<p style=\"font-size: 24px\">Giảm giá 20%</p>"],
        x: "Trong thuộc tính style, mỗi cặp “tên: giá trị” ngăn với cặp sau bằng dấu chấm phẩy; color nhận màu (red), font-size nhận cỡ chữ (24px).", lv: 3 },
      { topic: "Tạo danh sách, bảng", type: "mc", q: "Thẻ nào dùng để đặt tiêu đề cho một bảng, viết ngay sau thẻ mở <table>?",
        o: ["<caption>", "<legend>", "<title>", "<th>"],
        x: "Thẻ caption tạo tiêu đề của bảng, đặt ngay sau thẻ mở table và trước hàng đầu tiên; title là tên của cả trang web, legend đặt tên cho một nhóm ô của biểu mẫu.", lv: 1 },
      { topic: "Tạo danh sách, bảng", type: "tf4", q: "Với đoạn mã “<ul style=\"list-style-type: square\"><li>Bút</li><li>Thước</li></ul>”, mỗi ý sau đúng hay sai?",
        o: ["Các mục được đánh số 1, 2.", "Đổi square thành none thì các mục không có kí tự đầu dòng.", "Mỗi mục có kí tự đầu dòng là hình vuông nhỏ.", "Có thể đặt một danh sách khác vào trong một thẻ li để tạo danh sách lồng nhau."], a: [false, true, true, true],
        x: "a) Sai: ul là danh sách không có thứ tự, các mục không được đánh số. b) Đúng: giá trị none bỏ kí tự đầu dòng. c) Đúng: square dùng hình vuông nhỏ làm kí tự đầu dòng. d) Đúng: đặt danh sách con trong thẻ li của mục cha thì tạo danh sách lồng nhau.", lv: 2 },
      { topic: "Tạo danh sách, bảng", type: "essay", q: "Em hãy viết đoạn mã HTML tạo một bảng có viền gồm 3 hàng, 3 cột: hàng 1 là ba ô tiêu đề “Tiết”, “Thứ Hai”, “Thứ Ba”; hàng 2 gồm “1”, “Toán”, “Ngữ văn”; hàng 3 gồm ô “2” và một ô “Tin học” kéo dài qua hai cột Thứ Hai, Thứ Ba.",
        rubric: [{ c: "Có cặp thẻ table mở, đóng, có viền (border=\"1\" hoặc thuộc tính style có border)", p: 0.5 }, { c: "Hàng 1 viết bằng thẻ tr với ba ô tiêu đề th: Tiết, Thứ Hai, Thứ Ba", p: 0.5 }, { c: "Hàng 2 viết bằng thẻ tr với ba ô td: 1, Toán, Ngữ văn", p: 0.5 }, { c: "Hàng 3 có ô td “2” và ô td có colspan=\"2\" chứa “Tin học”, không viết thêm ô thứ ba", p: 0.5 }],
        x: "Bài gợi ý: “<table border=\"1\"><tr><th>Tiết</th><th>Thứ Hai</th><th>Thứ Ba</th></tr><tr><td>1</td><td>Toán</td><td>Ngữ văn</td></tr><tr><td>2</td><td colspan=\"2\">Tin học</td></tr></table>”. Ô “Tin học” chiếm hai cột nên hàng 3 chỉ viết hai cặp thẻ td.", lv: 3 },
      { topic: "Tạo liên kết", type: "mc", q: "Phần “Kết luận” của một trang web được đặt id=\"ket-luan\". Muốn bấm vào một liên kết ở đầu trang là nhảy tới phần này, thuộc tính href của liên kết cần có giá trị nào?",
        o: ["#ket-luan", "ket-luan", "ket-luan.html", "id=ket-luan"],
        x: "Liên kết tới một vị trí trong cùng trang dùng dấu # rồi đến id của phần tử đích, nên href có giá trị #ket-luan.", lv: 1 },
      { topic: "Tạo liên kết", type: "mc", q: "Đoạn mã nào làm cho ảnh logo.png trở thành một liên kết tới trang lien-he.html?",
        o: ["<a href=\"lien-he.html\"><img src=\"logo.png\"></a>", "<img src=\"lien-he.html\"><a href=\"logo.png\"></a>", "<a href=\"logo.png\"><img src=\"lien-he.html\"></a>", "<a src=\"lien-he.html\"><img href=\"logo.png\"></a>"],
        x: "Đặt thẻ img (src là tên tệp ảnh) vào giữa thẻ mở và thẻ đóng của thẻ a, còn href của thẻ a là trang cần mở: bấm vào ảnh sẽ mở trang lien-he.html.", lv: 3 },
      { topic: "Chèn tệp tin đa phương tiện và khung nội tuyến vào trang web", type: "mc", q: "Thuộc tính nào của thẻ <video> làm hiện các nút phát, tạm dừng và chỉnh âm lượng cho người xem?",
        o: ["controls", "autoplay", "poster", "muted"],
        x: "controls là thuộc tính bật, tắt (không cần giá trị); có nó thì trình duyệt hiện thanh điều khiển với nút phát, tạm dừng, âm lượng.", lv: 1 },
      { topic: "Chèn tệp tin đa phương tiện và khung nội tuyến vào trang web", type: "tf4", q: "Với đoạn mã “<video src=\"gioi-thieu.mp4\" width=\"320\" autoplay muted></video>”, mỗi ý sau đúng hay sai?",
        o: ["Mở trang là video tự phát ngay.", "Video phát có âm thanh.", "Video hiển thị với chiều rộng 320 pixel.", "Thêm thuộc tính poster với tên một tệp ảnh thì ảnh đó hiện trong lúc video chưa phát."], a: [true, false, true, true],
        x: "a) Đúng: có autoplay, kèm muted nên trình duyệt cho tự phát. b) Sai: muted làm video phát không có tiếng. c) Đúng: width=\"320\" đặt chiều rộng 320 pixel. d) Đúng: poster là ảnh hiện khi video chưa chạy.", lv: 2 },
      { topic: "Tạo biểu mẫu", type: "mc", q: "Phần tử nào của biểu mẫu tạo một vùng nhập được nhiều dòng chữ, ví dụ để viết ý kiến góp ý?",
        o: ["<textarea>", "<select>", "<fieldset>", "<label>"],
        x: "Thẻ textarea tạo vùng nhập nhiều dòng; số dòng, số cột hiện ra đặt bằng rows, cols. Thẻ select tạo danh sách thả xuống, fieldset vẽ khung bao một nhóm phần tử.", lv: 1 },
      { topic: "Tạo biểu mẫu", type: "mc", q: "Một bạn viết “<label for=\"ten\">Họ tên:</label> <input type=\"text\" id=\"hoten\" name=\"hoten\">”. Nháy chuột vào chữ “Họ tên:” thì con trỏ không vào ô nhập. Sửa thế nào cho đúng?",
        o: ["Đổi for=\"ten\" thành for=\"hoten\"", "Đổi type=\"text\" thành type=\"number\"", "Bỏ thuộc tính name của ô nhập", "Chuyển nhãn xuống sau ô nhập"],
        x: "Thuộc tính for của nhãn phải trùng với id của ô nhập thì nháy vào nhãn con trỏ mới vào ô đó; ở đây id là hoten nên sửa thành for=\"hoten\".", lv: 3 }
    ]
  },
  /* ---------- Tin học 12 · Kiểm tra giữa học kì II (Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng
     và Định hướng Khoa học máy tính, Chủ đề 4 phần CSS Bài 13–17 và Chủ đề 5 Bài 19–20; Phiên N12-gk2-tin-congnghe) ----------
     Phạm vi theo nguồn đa số tra được (đề cương giữa kì II của một trường: Bài 16–21; một đề giữa kì II: CSS và nghề sửa chữa, bảo trì máy
     tính, quản trị), khác mặc định ban đầu Bài 13–18; bài thực hành Bài 18 và Bài 21 Hội thảo hướng nghiệp không ra chủ đề riêng. Hai đề cố
     định 25 câu (CSS 19 câu, hướng nghiệp 6 câu), chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng trên 7 chủ đề theo tên bài của sách (ma trận
     ở data/banks/index.js). Hai đề là kho của đề ngẫu nhiên "tin12-gk2-ngau-nhien" (không có câu riêng nên không ghi vào file này), nên ô
     (chủ đề, mức) nào cũng có đúng gấp đôi số câu ô đó rút; mỗi câu một ý riêng, để câu cùng chủ đề (đề "Ôn chủ đề" rút chung) không lộ đáp
     án của nhau. Dạng câu theo khung Công văn 7991: nhiều lựa chọn, đúng/sai 4 ý (mỗi đề 5 câu, kiểu Đ/S không lặp), trả lời ngắn bằng số,
     một câu nối, 2 câu tự luận tự chấm (Đề 1: kế hoạch xử lí sự cố phòng tin học; Đề 2: viết tệp CSS ngoài và dòng mã kết nối). Mã CSS theo
     sách in năm 2026: trọng số của bộ chọn là tổng 100 (id), 10 (lớp, lớp giả, bộ chọn thuộc tính), 1 (phần tử, phần tử giả) như Bảng 17.4;
     thứ tự ưu tiên như Bảng 17.3; chỉ ba lớp giả :link, :visited, :hover; margin, padding một giá trị; màu theo tên, rgb() bằng số hay phần
     trăm, #rrggbb, hsl(). Không hỏi chỗ sách viết khác chuẩn CSS: giá trị “italics” của font-style, ngưỡng đậm 500 của font-weight, kế thừa
     của background-color, chiều rộng khung (Hình 16.3 vẽ width phủ cả vùng đệm), kí hiệu * cạnh tranh với giá trị kế thừa, em lồng nhau.
     tests/tin-congnghe12-gk2.js đọc lại mọi đoạn mã bằng một bộ đọc HTML, CSS nhỏ rồi áp mẫu định dạng (trọng số, thứ tự, kế thừa) để
     so với đáp án.
     Câu tự soạn, đối chiếu với sách in năm 2026; không dùng ví dụ, mã mẫu, bài tập của sách (Lịch sử CSS, Håkon Wium Lie, styles.css,
     Kĩ thuật chia để trị, Trời Hà Nội xanh, LỢI ÍCH CỦA CSS, Thư Bác Hồ gửi học sinh, lớp test, warning, id home, p11, p123, bảng 16 tên màu,
     trọng số 2, 110, 22, 102, câu lạc bộ ngoại khoá, WannaCry, British Airways, Sony, công ti kinh doanh trực tuyến). Cách xếp mức: nêu khái
     niệm, tên thuộc tính, ý nghĩa giá trị, công việc, ngành học như sách là Biết; đọc mã để biết kết quả hiển thị, tính trọng số, phân loại
     một trường hợp là Hiểu; chọn hoặc viết mẫu định dạng cho một yêu cầu, tính giá trị màu, cỡ chữ, xử lí tình huống là Vận dụng. */
  "tin12-gk2-de1": {
    note: "Sách Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng và Định hướng Khoa học máy tính. Phạm vi giữa học kì II theo đề cương, đề giữa kì II tra được: Chủ đề 4 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 13–18) 19 câu; Chủ đề 5 Hướng nghiệp với tin học (Bài 19–20) 6 câu. Mã HTML, CSS được hỏi qua các đoạn mã trong đề và trong hình; bài thực hành Bài 18 không có phần làm trên máy. Trường chỉ kiểm tra phần CSS (Bài 13–18), hoặc kiểm tra cả Bài 21, thì phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Khái niệm, vai trò của CSS", type: "mc", q: "Trong mẫu định dạng “h3 {color: navy; text-align: center;}”, phần “color: navy;” được gọi là gì?", o: ["Một quy định gồm thuộc tính và giá trị", "Bộ chọn chỉ ra thẻ được định dạng", "Một thẻ HTML nằm trong thẻ h3", "Một lớp giả có sẵn của CSS"], x: "Mỗi cặp “thuộc tính: giá trị;” viết giữa hai dấu ngoặc nhọn là một quy định: ở đây thuộc tính color nhận giá trị navy. Phần đứng trước dấu ngoặc nhọn (h3) mới là bộ chọn.", lv: 1 },
      { topic: "Khái niệm, vai trò của CSS", type: "tf4", q: "Mỗi ý sau về các cách đưa mẫu định dạng CSS vào trang web đúng hay sai?", o: ["Mẫu viết trong thẻ style ở phần head chỉ áp dụng cho chính tệp HTML chứa thẻ style đó.", "Đoạn mã “<p style=\"color: teal;\">Lịch trực</p>” là cách thiết lập CSS trong.", "Bộ chọn “h2, h4” áp dụng mẫu định dạng cho cả các thẻ h2 và các thẻ h4.", "Một tệp CSS ngoài gồm cả thẻ HTML lẫn mẫu định dạng, viết theo cú pháp của HTML."], a: [true, false, true, false], x: "a) Đúng: CSS trong chỉ có tác dụng với tệp HTML hiện thời. b) Sai: viết bằng thuộc tính style ngay trong thẻ là CSS nội tuyến. c) Đúng: nhiều thẻ ngăn bằng dấu phẩy thì mẫu áp dụng cho mọi thẻ đó. d) Sai: tệp CSS ngoài chỉ chứa các mẫu định dạng viết bằng ngôn ngữ CSS, độc lập với HTML.", lv: 2 },
      { topic: "Khái niệm, vai trò của CSS", type: "mc", q: "Website của câu lạc bộ cờ vua có 12 trang, trang nào cũng được kết nối với cùng một tệp “covua.css”. Ban biên tập muốn đổi màu chữ của mọi tiêu đề h2 trên cả 12 trang. Cách làm nào nhanh nhất?", o: ["Sửa mẫu định dạng của h2 trong tệp covua.css", "Thêm thẻ style vào phần head của từng trang", "Gắn thuộc tính style vào từng thẻ h2 của 12 trang", "Tạo riêng một tệp CSS mới cho mỗi trang"], x: "Các trang cùng dùng một tệp CSS ngoài nên chỉ cần sửa một lần trong tệp covua.css là mọi tiêu đề h2 của 12 trang đổi màu. Ba cách còn lại phải sửa ở từng trang, mất thời gian và dễ không thống nhất.", lv: 3 },
      { topic: "Định dạng văn bản bằng CSS", type: "mc", q: "Muốn chữ của mọi đoạn văn được căn đều hai bên lề, cần quy định nào?", o: ["text-align: justify;", "text-indent: 2em;", "text-decoration: none;", "text-align: right;"], x: "Thuộc tính text-align căn lề dòng văn bản; giá trị justify căn đều hai bên, right căn phải. text-indent là thụt lề dòng đầu, text-decoration là đường kẻ trang trí.", lv: 1 },
      { topic: "Định dạng văn bản bằng CSS", type: "mc", q: "Với quy định “font-family: Arial, Verdana, sans-serif;”, trình duyệt chọn phông chữ thế nào?", o: ["Dùng phông đầu tiên trong danh sách mà máy có sẵn", "Dùng mỗi phông cho một phần của đoạn văn bản", "Luôn dùng phông đứng cuối cùng của danh sách", "Chọn ngẫu nhiên một phông trong danh sách"], x: "Trình duyệt tìm các phông theo thứ tự từ trái sang phải: có Arial thì dùng Arial, không có thì thử Verdana; không có cả hai thì dùng một phông bất kì thuộc loại sans-serif ghi ở cuối danh sách.", lv: 1 },
      { topic: "Định dạng văn bản bằng CSS", type: "num", q: "Một trang có hai mẫu định dạng “html {font-size: 18px;}” và “.chu-thich {font-size: 75%;}”. Đoạn mã “<p>Giá vé <span class=\"chu-thich\">chưa gồm phí gửi xe</span></p>” nằm trong body, các thẻ p, body không có mẫu cỡ chữ riêng. Chữ “chưa gồm phí gửi xe” có cỡ bao nhiêu pixel?", ans: 13.5, unit: "px", x: "Thẻ p, body kế thừa cỡ chữ 18 px từ phần tử gốc html. Cỡ chữ theo phần trăm tính theo cỡ chữ của phần tử cha (p): 75% × 18 = 13,5 (px).", lv: 2 },
      { topic: "Định dạng văn bản bằng CSS", type: "mc", q: "Đoạn văn có class=\"trich-dan\" cần: phông chữ có chiều rộng đều nhau, chữ đậm, dòng đầu tiên thụt vào 30 pixel. Mẫu định dạng nào đáp ứng đúng yêu cầu?", o: [".trich-dan {font-family: monospace; font-weight: bold; text-indent: 30px;}", ".trich-dan {font-family: cursive; font-weight: bold; text-indent: 30px;}", "#trich-dan {font-family: monospace; font-weight: bold; text-indent: 30px;}", ".trich-dan {font-family: monospace; font-weight: normal; text-indent: -30px;}"], x: "Lớp viết bằng dấu chấm (.trich-dan); dấu # là bộ chọn id. Phông có chiều rộng đều nhau là monospace (cursive là chữ viết tay); chữ đậm là font-weight: bold; text-indent dương thì dòng đầu thụt vào, âm thì thành thụt lề treo.", lv: 3 },
      { topic: "Tạo màu cho chữ và nền", type: "mc", q: "Trong cách viết màu “hsl(H, S, L)”, tham số S cho biết điều gì?", o: ["Độ bão hoà, tức độ đậm đặc của màu", "Vị trí của màu trên vòng tròn màu", "Độ sáng của màu, tính theo phần trăm", "Lượng màu xanh lá có trong màu đó"], x: "Hệ màu HSL có ba tham số: H (Hue) chỉ vị trí của màu trên vòng tròn màu, S (Saturation) là độ bão hoà, cho biết màu đậm đặc đến mức nào, L (Lightness) là độ sáng.", lv: 1 },
      { topic: "Tạo màu cho chữ và nền", type: "mc", q: "Mã màu nào dưới đây cùng một màu với “rgb(70, 130, 180)”?", o: ["#4682B4", "#4682C4", "#B48246", "#468280"], x: "Đổi từng số sang hệ đếm cơ số 16: 70 = 46, 130 = 82, 180 = B4, viết theo thứ tự đỏ, xanh lá, xanh dương nên được #4682B4. #B48246 viết ngược thứ tự; C4 là 196, 80 là 128.", lv: 2 },
      { topic: "Tạo màu cho chữ và nền", type: "tf4", q: "Cho đoạn mã HTML trong hình. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 202"><rect x="1" y="1" width="318" height="200" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;div&gt;</text><text x="28" y="46" font-size="14">&lt;h2&gt;Bảng tin&lt;/h2&gt;</text><text x="28" y="66" font-size="14">&lt;p&gt;</text><text x="44" y="86" font-size="14">Họp &lt;em&gt;lớp&lt;/em&gt;,</text><text x="44" y="106" font-size="14">&lt;strong&gt;trực nhật&lt;/strong&gt;</text><text x="28" y="126" font-size="14">&lt;/p&gt;</text><text x="28" y="146" font-size="14">&lt;strong&gt;Hạn: thứ Sáu&lt;/strong&gt;</text><text x="12" y="166" font-size="14">&lt;/div&gt;</text><text x="12" y="186" font-size="14">&lt;strong&gt;Cuối trang&lt;/strong&gt;</text></svg>', o: ["Mẫu “div strong {color: green;}” áp dụng cho chữ “Cuối trang”.", "Mẫu “p > strong {color: green;}” áp dụng cho chữ “trực nhật”.", "Mẫu “h2 + strong {color: green;}” áp dụng cho chữ “Hạn: thứ Sáu”.", "Mẫu “p ~ strong {color: green;}” áp dụng cho chữ “Hạn: thứ Sáu”."], a: [false, true, false, true], x: "a) Sai: “Cuối trang” không nằm trong div. b) Đúng: strong “trực nhật” là phần tử con trực tiếp của p. c) Sai: phần tử liền ngay sau h2 là p, không phải strong. d) Đúng: strong “Hạn: thứ Sáu” đứng sau p và cùng phần tử cha div.", lv: 2 },
      { topic: "Tạo màu cho chữ và nền", type: "num", q: "Màu “rgb(20%, 60%, 100%)” được viết lại bằng hàm rgb() với ba số nguyên từ 0 đến 255. Tham số thứ hai (xanh lá) bằng bao nhiêu?", ans: 153, x: "Mỗi tham số phần trăm là phần trăm của 255: 60% × 255 = 153. Màu viết lại là rgb(51, 153, 255).", lv: 3 },
      { topic: "Định dạng khung", type: "match", q: "Nối mỗi giá trị của border-style với kiểu đường viền khung tương ứng.", l: ["solid", "dotted", "dashed"], r: ["đường viền là một nét liền", "đường viền gồm các chấm nhỏ", "đường viền gồm các đoạn gạch ngắn", "đường viền gồm hai nét song song"], x: "solid: nét liền; dotted: các chấm; dashed: các đoạn gạch ngắn (nét đứt). Hai nét song song là giá trị double.", lv: 1 },
      { topic: "Định dạng khung", type: "tf4", q: "Cho đoạn mã trong hình. Mỗi ý sau về chữ hiển thị trên trình duyệt đúng hay sai?", svg: '<svg viewBox="0 0 320 202"><rect x="1" y="1" width="318" height="200" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;style&gt;</text><text x="28" y="46" font-size="14">.tin { color: green; }</text><text x="28" y="66" font-size="14">.tin.gap { color: red; }</text><text x="28" y="86" font-size="14">p.tin { font-weight: bold; }</text><text x="28" y="106" font-size="14">#c { color: gray; }</text><text x="12" y="126" font-size="14">&lt;/style&gt;</text><text x="12" y="146" font-size="14">&lt;p class="tin"&gt;Tin A&lt;/p&gt;</text><text x="12" y="166" font-size="14">&lt;p class="tin gap"&gt;Tin B&lt;/p&gt;</text><text x="12" y="186" font-size="14">&lt;div class="tin gap" id="c"&gt;Tin C&lt;/div&gt;</text></svg>', o: ["Chữ “Tin A” màu xanh lá và in đậm.", "Chữ “Tin B” màu xanh lá.", "Chữ “Tin C” in đậm.", "Chữ “Tin C” màu xám."], a: [true, false, false, true], x: "a) Đúng: “Tin A” thuộc lớp tin và là thẻ p. b) Sai: “Tin B” thuộc đồng thời hai lớp tin và gap nên mẫu .tin.gap đổi màu đỏ. c) Sai: mẫu p.tin chỉ áp dụng cho thẻ p, “Tin C” nằm trong div. d) Đúng: “Tin C” có id=\"c\", mẫu #c cho màu xám.", lv: 2 },
      { topic: "Định dạng khung", type: "mc", q: "Một biểu mẫu có ba ô nhập: “<input type=\"text\" name=\"ho-ten\">”, “<input type=\"number\" name=\"tuoi\">”, “<input type=\"text\" name=\"lop\">”. Muốn chỉ hai ô nhập chữ có viền liền màu xanh lam, cần mẫu định dạng nào?", o: ["input[type=\"text\"] {border: 2px solid blue;}", "input {border: 2px solid blue;}", "[name] {border: 2px solid blue;}", "input[name=\"tuoi\"] {border: 2px solid blue;}"], x: "Bộ chọn thuộc tính input[type=\"text\"] chỉ chọn các ô có type=\"text\", tức hai ô họ tên và lớp. Bộ chọn input hay [name] chọn cả ba ô; input[name=\"tuoi\"] chỉ chọn ô nhập số.", lv: 3 },
      { topic: "Định dạng khung", type: "mc", q: "Trang có ba khung bảng tin cùng viết “<div class=\"bang-tin\">…</div>”. Bạn muốn riêng khung thứ hai có nền vàng, hai khung kia giữ nguyên. Cách làm nào đúng?", o: ["Thêm id=\"bt2\" cho khung thứ hai và viết mẫu “#bt2 {background-color: yellow;}”", "Viết mẫu “.bang-tin {background-color: yellow;}”", "Đặt id=\"bang-tin\" cho cả ba khung rồi viết mẫu “#bang-tin {background-color: yellow;}”", "Viết mẫu “div {background-color: yellow;}”"], x: "Mỗi id là duy nhất trong trang nên dùng id riêng cho khung thứ hai rồi viết mẫu với bộ chọn #bt2. Mẫu .bang-tin hay div đổi nền cả ba khung; đặt cùng một id cho ba khung là sai quy định.", lv: 3 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "mc", q: "Mẫu “a:hover {color: orange;}” làm liên kết có chữ màu cam vào lúc nào?", o: ["Lúc người dùng đưa con trỏ chuột lên liên kết", "Lúc liên kết chưa được mở lần nào", "Lúc liên kết đã được mở ít nhất một lần", "Lúc trang web vừa tải xong"], x: ":hover là lớp giả chỉ trạng thái con trỏ chuột đang nằm trên phần tử. Liên kết chưa mở là :link, đã mở là :visited.", lv: 1 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "num", q: "Theo cách tính trọng số của CSS, bộ chọn “ul#menu li.moi > a” có trọng số bao nhiêu?", ans: 113, x: "Trọng số là tổng giá trị các thành phần: ba phần tử ul, li, a mỗi phần tử 1; id #menu 100; lớp .moi 10. Kí hiệu > không có trọng số. Tổng: 3 + 100 + 10 = 113.", lv: 2 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "tf4", q: "Cho đoạn mã trong hình. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 242"><rect x="1" y="1" width="318" height="240" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;style&gt;</text><text x="28" y="46" font-size="14">#gia { color: red; }</text><text x="28" y="66" font-size="14">.moi { color: green; }</text><text x="28" y="86" font-size="14">span { color: orange; }</text><text x="28" y="106" font-size="14">p span { color: blue; }</text><text x="12" y="126" font-size="14">&lt;/style&gt;</text><text x="12" y="146" font-size="14">&lt;p&gt;</text><text x="28" y="166" font-size="14">Giá: &lt;span id="gia"&gt;80&lt;/span&gt;</text><text x="28" y="186" font-size="14">&lt;span class="moi"&gt;60&lt;/span&gt;</text><text x="28" y="206" font-size="14">&lt;span&gt;45&lt;/span&gt;</text><text x="12" y="226" font-size="14">&lt;/p&gt;</text></svg>', o: ["Chữ “80” có màu đỏ.", "Chữ “60” có màu xanh dương.", "Chữ “45” có màu xanh dương.", "Nếu đổi chỗ hai mẫu cuối (mẫu span viết sau cùng) thì chữ “45” vẫn có màu xanh dương."], a: [true, false, true, true], x: "a) Đúng: mẫu #gia có trọng số 100, lớn nhất. b) Sai: mẫu .moi trọng số 10 lớn hơn p span (2) và span (1) nên “60” màu xanh lá. c) Đúng: “45” chỉ khớp span (1) và p span (2), mẫu p span thắng. d) Đúng: thứ tự viết chỉ xét khi trọng số bằng nhau; p span vẫn có trọng số lớn hơn span.", lv: 2 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "mc", q: "Trang có mẫu “#tin-moi p {color: gray;}”. Bạn thêm một mẫu vào cuối thẻ style để đoạn văn có class=\"noi-bat\" nằm trong khối “<div id=\"tin-moi\">” có chữ màu đỏ. Mẫu nào làm được?", o: ["#tin-moi p.noi-bat {color: red;}", ".noi-bat {color: red;}", "p.noi-bat {color: red;}", "div p.noi-bat {color: red;}"], x: "Mẫu cũ có trọng số 100 + 1 = 101. #tin-moi p.noi-bat có trọng số 100 + 1 + 10 = 111 nên thắng. Ba mẫu còn lại có trọng số 10, 11, 12, nhỏ hơn 101 nên chữ vẫn màu xám dù viết sau.", lv: 3 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "mc", q: "Công việc nào sau đây thuộc nhóm công việc liên quan tới phần mềm của nghề sửa chữa và bảo trì máy tính?", o: ["Cập nhật hệ điều hành và ứng dụng lên phiên bản mới", "Thay ổ cứng hỏng bằng một ổ cứng dung lượng lớn hơn", "Lắp thêm một thanh RAM cho máy tính để bàn", "Thay màn hình vỡ của một máy tính xách tay"], x: "Cài đặt, cập nhật phần mềm (hệ điều hành, ứng dụng) là việc liên quan tới phần mềm. Thay ổ cứng, lắp thêm RAM, thay màn hình là việc liên quan tới phần cứng.", lv: 1 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "mc", q: "Người làm nghề sửa chữa và bảo trì máy tính cần kĩ năng giao tiếp chủ yếu để làm gì?", o: ["Hiểu yêu cầu của khách, giải thích cách xử lí", "Tự viết mã nguồn cho các phần mềm mới mà khách đặt hàng", "Thiết kế bo mạch chủ cho các dòng máy tính mới", "Lập kế hoạch thu chi cho cửa hàng"], x: "Kĩ năng giao tiếp giúp người thợ nắm đúng yêu cầu của người dùng, giải thích, tư vấn giải pháp kĩ thuật bằng lời dễ hiểu. Các việc còn lại không phải mục đích của kĩ năng giao tiếp trong nghề này.", lv: 1 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "essay", q: "Phòng tin học của trường có 30 máy tính. Gần đây nhiều máy khởi động rất chậm và tự hiện quảng cáo lạ; một máy bật lên không hiện gì trên màn hình dù đèn nguồn vẫn sáng; một số bạn lớp 10 chưa biết lưu bài vào thư mục chung trên mạng của phòng. Em hãy lập kế hoạch xử lí: nêu việc cần làm cho từng tình huống, cho biết mỗi việc thuộc nhóm phần mềm, phần cứng hay hỗ trợ người dùng, và nêu một việc nên làm định kì để hạn chế sự cố.", rubric: [{ c: "Máy chậm, hiện quảng cáo lạ: quét, diệt mã độc, gỡ phần mềm lạ (nhóm phần mềm)", p: 0.5 }, { c: "Máy không lên hình: kiểm tra dây nối, màn hình, các linh kiện (card màn hình, RAM), sửa hoặc thay thế (nhóm phần cứng)", p: 0.5 }, { c: "Hướng dẫn các bạn lớp 10 lưu bài vào thư mục chung (nhóm hỗ trợ người dùng)", p: 0.5 }, { c: "Nêu được một việc bảo trì định kì phù hợp (kiểm tra máy theo lịch, cài phần mềm phòng chống virus, sao lưu dữ liệu…)", p: 0.5 }], x: "Bài gợi ý: (1) Các máy chậm, hiện quảng cáo lạ có thể nhiễm mã độc: quét, diệt mã độc, gỡ các phần mềm lạ (phần mềm). (2) Máy sáng đèn nguồn mà không lên hình: kiểm tra dây nối và màn hình, rồi đến card màn hình, RAM; linh kiện hỏng thì sửa hoặc thay (phần cứng). (3) Hướng dẫn các bạn lớp 10 cách lưu bài vào thư mục chung (hỗ trợ người dùng). (4) Định kì mỗi tháng kiểm tra các máy, giữ phần mềm phòng chống virus luôn hoạt động và sao lưu dữ liệu quan trọng.", lv: 3 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "mc", q: "Công việc “theo dõi hiệu suất của mạng, xử lí sự cố để mạng của công ti chạy ổn định” là việc chính của nghề nào?", o: ["Quản trị mạng", "Bảo mật hệ thống thông tin", "Quản trị và bảo trì hệ thống", "Phân tích dữ liệu kinh doanh"], x: "Người quản trị mạng cài đặt, cấu hình mạng, theo dõi hiệu suất và xử lí sự cố để mạng hoạt động ổn định. Bảo mật hệ thống thông tin lo chống tấn công; quản trị và bảo trì hệ thống lo toàn bộ phần cứng, phần mềm của hệ thống.", lv: 1 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "mc", q: "Học sinh muốn theo nhóm nghề quản trị trong ngành Công nghệ thông tin có thể chọn ngành học nào dưới đây?", o: ["Quản trị hệ thống", "Quản trị kinh doanh", "Kĩ thuật xây dựng", "Thiết kế thời trang"], x: "Theo sách, các ngành học gắn với nhóm nghề này gồm Quản trị mạng máy tính, Quản trị hệ thống, An ninh mạng, Hệ thống thông tin… Quản trị kinh doanh là ngành kinh tế, không đào tạo quản trị hệ thống máy tính.", lv: 1 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "tf4", q: "Mỗi ý sau về kiến thức, kĩ năng của người làm nghề trong nhóm nghề quản trị đúng hay sai?", o: ["Người làm nghề cần nắm và làm đúng các quy định pháp luật về an ninh mạng.", "Biết cài đặt hệ điều hành, cấu hình và giữ cho nó chạy ổn định là kiến thức về quản lí hệ thống.", "Kĩ năng tự học, cập nhật kiến thức ít cần thiết vì công nghệ thông tin hầu như không đổi.", "Người làm nghề chỉ cần thành thạo các phần mềm soạn thảo văn bản, bảng tính."], a: [true, true, false, false], x: "a) Đúng: kiến thức về luật pháp và tuân thủ quy định là một yêu cầu của nghề. b) Đúng: đó là kiến thức về quản lí hệ thống. c) Sai: công nghệ thay đổi nhanh nên kĩ năng tự nghiên cứu, cập nhật kiến thức rất cần thiết. d) Sai: cần kiến thức về mạng, bảo mật, quản lí hệ thống, không chỉ phần mềm văn phòng.", lv: 2 }
    ]
  },
  "tin12-gk2-de2": {
    note: "Sách Kết nối tri thức, Tin học 12, phần chung của hai sách Định hướng Tin học ứng dụng và Định hướng Khoa học máy tính. Phạm vi giữa học kì II theo đề cương, đề giữa kì II tra được: Chủ đề 4 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 13–18) 19 câu; Chủ đề 5 Hướng nghiệp với tin học (Bài 19–20) 6 câu. Mã HTML, CSS được hỏi qua các đoạn mã trong đề và trong hình; bài thực hành Bài 18 không có phần làm trên máy. Trường chỉ kiểm tra phần CSS (Bài 13–18), hoặc kiểm tra cả Bài 21, thì phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Khái niệm, vai trò của CSS", type: "mc", q: "Ngoài thẻ link, cách nào dưới đây cũng kết nối được một trang HTML với tệp CSS ngoài “mau-chung.css”?", o: ["<style> @import \"mau-chung.css\"; </style>", "<style href=\"mau-chung.css\"></style>", "<p style=\"mau-chung.css\">Mẫu</p>", "<a href=\"mau-chung.css\">Mẫu</a>"], x: "Lệnh @import đặt trong phần tử style ở phần head cũng kết nối trang với tệp CSS ngoài. Thẻ style không có thuộc tính href; thuộc tính style chứa các quy định chứ không chứa tên tệp; thẻ a chỉ tạo liên kết để mở tệp.", lv: 1 },
      { topic: "Khái niệm, vai trò của CSS", type: "mc", q: "CSS tách việc nhập nội dung trang web khỏi việc định dạng. Điều này giúp ích gì cho người nhập nội dung?", o: ["Chỉ cần dùng thẻ HTML đúng ý nghĩa, không lo định dạng", "Không cần dùng bất kì thẻ HTML nào khi nhập nội dung trang web", "Phải định dạng lại từng đoạn văn ngay sau khi nhập", "Trang web tự sửa lỗi chính tả trong nội dung đã nhập"], x: "Khi định dạng được giao cho các mẫu CSS, người nhập nội dung chỉ dùng thẻ HTML cho đúng ý nghĩa (tiêu đề, đoạn văn, danh sách…); màu sắc, phông chữ do mẫu định dạng quyết định.", lv: 2 },
      { topic: "Khái niệm, vai trò của CSS", type: "essay", q: "Em hãy viết: (1) nội dung tệp “ban-tin.css” gồm hai mẫu định dạng: tiêu đề h1 có chữ màu xanh dương và căn giữa; mọi đoạn văn p dùng phông chữ không chân và dòng đầu tiên thụt vào 20 pixel; (2) dòng mã đặt trong phần head của trang “so-3.html” để kết nối trang này với tệp “ban-tin.css”.", rubric: [{ c: "Mẫu cho h1: bộ chọn h1, có color: blue; và text-align: center;", p: 0.5 }, { c: "Mẫu cho p: font-family có phông không chân (sans-serif ở cuối danh sách) và text-indent: 20px;", p: 0.5 }, { c: "Đúng cú pháp: bộ chọn, cặp ngoặc nhọn, mỗi quy định dạng “thuộc tính: giá trị;” kết thúc bằng dấu chấm phẩy", p: 0.5 }, { c: "Thẻ link đặt trong head, có href=\"ban-tin.css\" và rel=\"stylesheet\"", p: 0.5 }], x: "Bài gợi ý: tệp ban-tin.css gồm hai mẫu “h1 {color: blue; text-align: center;}” và “p {font-family: Arial, sans-serif; text-indent: 20px;}”. Trong phần head của trang so-3.html thêm dòng “<link href=\"ban-tin.css\" rel=\"stylesheet\">”.", lv: 3 },
      { topic: "Định dạng văn bản bằng CSS", type: "mc", q: "Quy định nào làm chữ có một đường kẻ ngang ở giữa dòng chữ, như chữ bị gạch bỏ?", o: ["text-decoration: line-through;", "text-decoration: overline;", "text-decoration: underline;", "text-indent: -20px;"], x: "text-decoration trang trí dòng văn bản bằng đường kẻ: line-through kẻ giữa dòng chữ, underline kẻ dưới chữ, overline kẻ phía trên chữ. text-indent âm là thụt lề treo.", lv: 1 },
      { topic: "Định dạng văn bản bằng CSS", type: "mc", q: "Viết “!important” ngay sau giá trị của một quy định trong mẫu định dạng thì có tác dụng gì?", o: ["Quy định đó được ưu tiên cao nhất, dù mẫu viết ở vị trí nào", "Mẫu đó chỉ áp dụng cho phần tử có thuộc tính id", "Quy định đó được áp dụng sang mọi trang của website", "Trình duyệt bỏ qua quy định đó khi hiển thị trang"], x: "Thuộc tính có đánh dấu !important được ưu tiên cao nhất, không phụ thuộc vị trí của mẫu; chỉ quy định có !important được ưu tiên, các quy định khác của mẫu vẫn theo luật thường.", lv: 1 },
      { topic: "Định dạng văn bản bằng CSS", type: "tf4", q: "Cho đoạn mã trong hình. Mỗi ý sau về trang hiển thị trên trình duyệt đúng hay sai?", svg: '<svg viewBox="0 0 320 282"><rect x="1" y="1" width="318" height="280" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;style&gt;</text><text x="28" y="46" font-size="14">body {</text><text x="44" y="66" font-size="14">color: navy;</text><text x="44" y="86" font-size="14">font-family: serif;</text><text x="28" y="106" font-size="14">}</text><text x="28" y="126" font-size="14">h1 { text-align: center; color: teal; }</text><text x="28" y="146" font-size="14">.muc { text-decoration: underline; }</text><text x="28" y="166" font-size="14">h1 { text-align: left; }</text><text x="12" y="186" font-size="14">&lt;/style&gt;</text><text x="12" y="206" font-size="14">&lt;h1&gt;Ngày hội đọc sách&lt;/h1&gt;</text><text x="12" y="226" font-size="14">&lt;p class="muc"&gt;</text><text x="28" y="246" font-size="14">Sách hay &lt;em&gt;mỗi tuần&lt;/em&gt;</text><text x="12" y="266" font-size="14">&lt;/p&gt;</text></svg>', o: ["Tiêu đề h1 được căn giữa.", "Chữ “mỗi tuần” có màu navy.", "Tiêu đề h1 có màu teal.", "Chữ của đoạn văn dùng phông chữ không chân."], a: [false, true, true, false], x: "a) Sai: hai mẫu h1 cùng quy định text-align, mẫu viết sau cùng (left) được áp dụng. b) Đúng: em không có mẫu màu riêng nên kế thừa màu navy từ p, p kế thừa từ body. c) Đúng: mẫu h1 đặt màu teal, thay cho màu kế thừa từ body. d) Sai: serif là phông chữ có chân.", lv: 2 },
      { topic: "Định dạng văn bản bằng CSS", type: "num", q: "Một trang có ba mẫu định dạng “html {font-size: 20px;}”, “h2 {font-size: 1.5rem;}” và “.nho {font-size: 80%;}”. Trong một thẻ h2 có “<span class=\"nho\">(cập nhật)</span>”. Chữ “(cập nhật)” có cỡ bao nhiêu pixel?", ans: 24, unit: "px", x: "Đơn vị rem tính theo cỡ chữ của phần tử gốc html: h2 có cỡ 1,5 × 20 = 30 (px). Phần trăm tính theo cỡ chữ của phần tử cha h2: span có cỡ 80% × 30 = 24 (px).", lv: 3 },
      { topic: "Tạo màu cho chữ và nền", type: "mc", q: "Mỗi màu trong hệ màu RGB gồm ba số nguyên, mỗi số từ 0 đến 255. Hệ màu này có tất cả bao nhiêu màu?", o: ["16 777 216", "65 536", "768", "256"], x: "Mỗi thành phần có 256 giá trị (từ 0 đến 255) nên số màu là 256 × 256 × 256 = 16 777 216.", lv: 1 },
      { topic: "Tạo màu cho chữ và nền", type: "mc", q: "Màu “hsl(0, 0%, 50%)” hiển thị trên trang web là màu gì?", o: ["Xám", "Đỏ tươi", "Đỏ sẫm", "Đen"], x: "Khi tham số thứ hai bằng 0%, màu không còn sắc nào nên chỉ là màu xám; tham số thứ ba 50% cho màu xám vừa, cùng màu với rgb(128, 128, 128).", lv: 2 },
      { topic: "Tạo màu cho chữ và nền", type: "tf4", q: "Mỗi ý sau về các cách viết màu trong CSS đúng hay sai?", o: ["Trong màu “#00FF00”, thành phần xanh lá bằng 0.", "Màu “hsl(0, 100%, 100%)” là màu đỏ tươi.", "“rgb(100%, 0%, 0%)” và “#FF0000” cùng là màu đỏ.", "“rgb(0, 0, 255)” và “hsl(240, 100%, 50%)” cùng một màu."], a: [false, false, true, true], x: "a) Sai: cặp kí tự giữa FF là thành phần xanh lá, bằng 255. b) Sai: tham số thứ ba bằng 100% cho màu trắng. c) Đúng: 100% của 255 là 255, mã FF cũng là 255, hai thành phần còn lại bằng 0. d) Đúng: góc 240° trên vòng tròn màu là màu xanh dương; với hai tham số 100%, 50% ta được xanh dương thuần, bằng rgb(0, 0, 255).", lv: 2 },
      { topic: "Tạo màu cho chữ và nền", type: "mc", q: "Bạn muốn các ô tiêu đề của bảng (thẻ th) có chữ màu vàng trên nền đen. Mẫu định dạng nào đúng?", o: ["th {color: #FFFF00; background-color: rgb(0, 0, 0);}", "th {color: #FFFF00; background-color: rgb(255, 255, 255);}", "th {color: #0000FF; background-color: rgb(0, 0, 0);}", "th {background-color: #FFFF00; color: rgb(0, 0, 0);}"], x: "color là màu chữ, background-color là màu nền. #FFFF00 có đỏ và xanh lá bằng 255, xanh dương bằng 0 nên là màu vàng; rgb(0, 0, 0) là màu đen.", lv: 3 },
      { topic: "Định dạng khung", type: "mc", q: "Thẻ nào dưới đây mặc định tạo phần tử khối, tức phần tử luôn bắt đầu ở một hàng mới và chiếm hết bề ngang trang?", o: ["li", "a", "strong", "label"], x: "Theo cách phân loại phần tử của CSS, li là phần tử khối; a, strong, label là phần tử nội tuyến, nằm trong dòng của phần tử khác.", lv: 1 },
      { topic: "Định dạng khung", type: "tf4", q: "Mỗi ý sau về cách đặt tên lớp (class) và mã định danh (id) đúng hay sai?", o: ["Bộ chọn “.Tin” và “.tin” chọn cùng những phần tử.", "Tên lớp “2a” không đúng quy định vì bắt đầu bằng chữ số.", "Tên id “muc_1” đúng quy định.", "Tên lớp “tin-moi” đúng quy định."], a: [false, true, true, true], x: "a) Sai: tên lớp phân biệt chữ in hoa, in thường nên đó là hai lớp khác nhau. b) Đúng: tên không được bắt đầu bằng chữ số. c) Đúng: muc_1 bắt đầu bằng chữ cái, không có dấu cách. d) Đúng: tin-moi bắt đầu bằng chữ cái, không có dấu cách hay kí tự đặc biệt.", lv: 2 },
      { topic: "Định dạng khung", type: "mc", q: "Trang luyện tập có đoạn “<p class=\"dap-an\">…</p>” chứa đáp án. Bạn muốn lúc đầu đoạn đáp án không hiển thị trên trang. Mẫu định dạng nào làm được?", o: [".dap-an {display: none;}", ".dap-an {display: inline;}", "#dap-an {display: none;}", "p {display: none;}"], x: "Giá trị none của thuộc tính display làm ẩn phần tử. Bộ chọn lớp viết bằng dấu chấm: .dap-an; #dap-an là bộ chọn id; mẫu p ẩn mọi đoạn văn của trang.", lv: 3 },
      { topic: "Định dạng khung", type: "mc", q: "Ô thông báo có viền, nhưng chữ bên trong nằm sát đường viền. Muốn có khoảng trống 12 pixel giữa chữ và đường viền, cần thêm quy định nào vào mẫu của ô?", o: ["padding: 12px;", "margin: 12px;", "border-width: 12px;", "text-indent: 12px;"], x: "Vùng đệm (padding) là khoảng cách từ phần nội dung đến đường viền của khung. margin là lề khung, nằm ngoài đường viền; border-width là độ dày đường viền; text-indent chỉ thụt dòng đầu.", lv: 3 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "mc", q: "Mẫu “p::first-letter {font-size: 200%;}” định dạng phần nào của mỗi đoạn văn?", o: ["Kí tự đầu tiên của đoạn", "Dòng đầu tiên của đoạn", "Phần đang được chọn bằng chuột", "Toàn bộ đoạn văn khi di chuột lên"], x: "::first-letter là phần tử giả chỉ kí tự đầu tiên; dòng đầu tiên là ::first-line, phần đang được chọn là ::selection.", lv: 1 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "mc", q: "Thẻ style có hai mẫu viết theo thứ tự “span.gia {color: blue;}” rồi “.gia {color: red;}”. Chữ trong “<span class=\"gia\">99 nghìn</span>” có màu gì?", o: ["Xanh dương", "Đỏ", "Đen", "Tím"], x: "span.gia có trọng số 1 + 10 = 11, .gia có trọng số 10. Mẫu trọng số lớn hơn được áp dụng, thứ tự viết chỉ xét khi trọng số bằng nhau, nên chữ màu xanh dương.", lv: 2 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "tf4", q: "Mỗi ý sau về thứ tự ưu tiên khi nhiều mẫu CSS cùng áp dụng cho một phần tử đúng hay sai?", o: ["Quy định trong thuộc tính style của thẻ được ưu tiên hơn mẫu có bộ chọn id.", "Phần tử chỉ lấy định dạng kế thừa từ phần tử cha khi không có mẫu nào áp dụng cho nó.", "Khi không có định dạng CSS nào, trình duyệt hiển thị theo mặc định của trình duyệt.", "Mẫu viết sau cùng luôn được áp dụng, dù trọng số nhỏ hơn mẫu viết trước."], a: [true, true, true, false], x: "a) Đúng: CSS trực tiếp (thuộc tính style) đứng trên trọng số. b) Đúng: kế thừa từ phần tử cha xếp dưới các mẫu áp dụng trực tiếp. c) Đúng: đó là mức thấp nhất, mặc định theo trình duyệt. d) Sai: thứ tự viết chỉ xét khi các mẫu có trọng số bằng nhau.", lv: 2 },
      { topic: "Các mức ưu tiên của bộ chọn", type: "mc", q: "Cho đoạn mã trong hình. Số “15” hiển thị màu gì?", svg: '<svg viewBox="0 0 320 242"><rect x="1" y="1" width="318" height="240" rx="8" fill="bg" stroke="line"/><text x="12" y="26" font-size="14">&lt;style&gt;</text><text x="28" y="46" font-size="14">#bang td { color: gray; }</text><text x="28" y="66" font-size="14">table .chan td { color: green; }</text><text x="28" y="86" font-size="14">tr.chan td.so { color: red; }</text><text x="28" y="106" font-size="14">td.so { color: blue; }</text><text x="12" y="126" font-size="14">&lt;/style&gt;</text><text x="12" y="146" font-size="14">&lt;table id="bang"&gt;</text><text x="28" y="166" font-size="14">&lt;tr class="chan"&gt;</text><text x="44" y="186" font-size="14">&lt;td class="so"&gt;15&lt;/td&gt;</text><text x="28" y="206" font-size="14">&lt;/tr&gt;</text><text x="12" y="226" font-size="14">&lt;/table&gt;</text></svg>', o: ["Xám", "Xanh lá", "Đỏ", "Xanh dương"], x: "Bốn mẫu đều áp dụng cho ô chứa số 15. Trọng số: #bang td = 100 + 1 = 101; table .chan td = 1 + 10 + 1 = 12; tr.chan td.so = 1 + 10 + 1 + 10 = 22; td.so = 1 + 10 = 11. Mẫu #bang td lớn nhất nên số 15 màu xám.", lv: 3 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "mc", q: "Với nghề sửa chữa và bảo trì máy tính, yếu tố nào được coi là quan trọng nhất khi làm việc?", o: ["Mức độ thành thạo trong công việc", "Có cửa hàng sửa chữa riêng ở mặt phố", "Thuộc lòng cấu hình của mọi loại máy", "Biết lập trình nhiều ngôn ngữ"], x: "Với nghề này, sách nhấn mạnh độ thành thạo khi làm việc là quan trọng nhất; vì vậy các trường nghề bậc cao đẳng chú trọng rèn kĩ năng thực hành.", lv: 1 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "mc", q: "Ngành đào tạo nào dưới đây gắn trực tiếp với nghề sửa chữa và bảo trì máy tính?", o: ["Công nghệ kĩ thuật phần cứng máy tính", "Kĩ thuật xây dựng công trình giao thông", "Công nghệ sinh học", "Thiết kế đồ hoạ trên máy tính"], x: "Các ngành học liên quan gồm Kĩ thuật sửa chữa, lắp ráp máy tính; Công nghệ kĩ thuật phần cứng máy tính; Công nghệ kĩ thuật phần mềm máy tính; Công nghệ thông tin.", lv: 1 },
      { topic: "Dịch vụ sửa chữa và bảo trì máy tính", type: "mc", q: "Quầy thu ngân của một cửa hàng mới lắp thêm máy in hoá đơn nhưng máy tính không in được, các phần mềm khác vẫn chạy tốt, máy in vẫn sáng đèn. Người thợ nên làm gì trước tiên?", o: ["Cài đặt đúng phần mềm điều khiển (driver) của máy in", "Thay bo mạch chủ, bộ nguồn của máy tính ở quầy thu ngân", "Cài đặt lại toàn bộ hệ điều hành của máy tính", "Đổi một máy tính khác cho quầy thu ngân"], x: "Máy tính vẫn chạy tốt, máy in có điện, thiết bị mới lắp thêm: nguyên nhân hay gặp là chưa có hoặc sai phần mềm điều khiển (driver) của thiết bị mới. Thay bo mạch chủ, cài lại hệ điều hành hay đổi máy là tốn kém mà chưa chắc đúng chỗ hỏng.", lv: 3 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "mc", q: "Hiểu biết về tấn công từ chối dịch vụ (DoS) và cách triển khai hệ thống phát hiện xâm nhập (IDS) thuộc nhóm kiến thức nào của người làm nghề quản trị?", o: ["Bảo mật thông tin", "Quản lí hệ thống", "Luật pháp và tuân thủ quy định", "Xử lí thông tin văn phòng"], x: "Các phương thức tấn công mạng như DoS, dò lỗ hổng và hệ thống phát hiện xâm nhập, tường lửa thuộc kiến thức về bảo mật thông tin.", lv: 1 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "mc", q: "Vì sao nhu cầu người làm công việc cài đặt, cấu hình, duy trì mạng máy tính ngày càng tăng?", o: ["Thiết bị và dịch vụ trực tuyến ngày càng nhiều", "Các tổ chức chuyển hẳn sang lưu hồ sơ bằng giấy", "Mạng máy tính ngày nay không còn bị tấn công", "Máy tính cá nhân ngày càng ít được sử dụng"], x: "Mạng vạn vật (IoT) làm số thiết bị kết nối tăng mạnh; làm việc từ xa, dùng dịch vụ đám mây, mua bán trực tuyến đòi hỏi mạng ổn định, an toàn, nên cần thêm nhiều người làm các công việc này.", lv: 1 },
      { topic: "Nhóm nghề quản trị trong ngành Công nghệ thông tin", type: "tf4", q: "Một trường đại học tuyển người cho nhóm nghề quản trị. Mỗi ý sau về việc phân công công việc đúng hay sai?", o: ["Xây dựng, triển khai các biện pháp bảo vệ dữ liệu của sinh viên trước tấn công mạng là việc của chuyên gia bảo mật hệ thống thông tin.", "Thay ổ cứng hỏng của máy chủ và cài đặt lại phần mềm là việc của người quản trị và bảo trì hệ thống.", "Viết phần mềm quản lí điểm cho sinh viên là việc chính của nhóm nghề quản trị.", "Cập nhật hệ điều hành, xử lí sự cố cho máy chủ của thư viện là việc của người quản trị và bảo trì hệ thống."], a: [true, true, false, true], x: "a) Đúng: bảo vệ dữ liệu trước các mối đe doạ là việc của chuyên gia bảo mật hệ thống thông tin. b) Đúng: nghề này quản lí cả phần cứng và phần mềm của hệ thống. c) Sai: viết phần mềm là việc của lập trình viên, thuộc nhóm nghề dịch vụ. d) Đúng: cài đặt, cập nhật, xử lí sự cố để hệ thống ổn định là việc của người quản trị và bảo trì hệ thống.", lv: 2 }
    ]
  }
});
